127	            name: index.name,
128	            keyPath: typeof index.keyPath === 'string' ? index.keyPath : undefined,
129	            keyPathArray: Array.isArray(index.keyPath) ? index.keyPath : undefined,
130	            multiEntry: index.multiEntry,
131	            unique: index.unique,
132	          };
133	        });
134	
