136	          name: storeName,
137	          records: records,
138	          indexes,
139	          autoIncrement: objectStore.autoIncrement,
140	          keyPath: typeof objectStore.keyPath === 'string' ? objectStore.keyPath : undefined,
141	          keyPathArray: Array.isArray(objectStore.keyPath) ? objectStore.keyPath : undefined,
142	        };
143	      }));
