157	      const entries = await this._directoryEntries(directory);
158	      entries.sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0);
159	
160	      const results = await Promise.all(entries.map(async ([name, handle]): Promise<OPFSEntry[]> => {
161	        const path = parentPath ? `${parentPath}/${name}` : name;
162	        if (handle.kind === 'directory')
163	          return [{ path, type: 'directory' }, ...await collect(handle as FileSystemDirectoryHandle, path)];
