214	        const objectStore = transaction.objectStore(store.name);
215	        await Promise.all(store.records.map(async record => {
216	          await this._idbRequestToPromise(
217	              objectStore.add(
218	                  record.value ?? parseEvaluationResultValue(record.valueEncoded),
219	                  record.key ?? parseEvaluationResultValue(record.keyEncoded),
220	              )
221	          );
222	        }));
223	      }));
224	    } finally {
