243	
244	    const entries = originState?.opfs ?? [];
245	    if (!entries.length)
246	      return;
247	
248	    for (const entry of entries) {
249	      const parts = entry.path.split('/');
250	      let directory = root;
251	      for (const part of parts.slice(0, -1))
252	        directory = await directory.getDirectoryHandle(part, { create: true });
253	
254	      const name = parts[parts.length - 1];
255	      if (entry.type === 'directory') {
256	        await directory.getDirectoryHandle(name, { create: true });
257	        continue;
258	      }
259	      const blob = await this._blobFromBase64(entry.base64!);
260	      const handle = await directory.getFileHandle(name, { create: true });
261	      const writable = await handle.createWritable();
262	      await writable.write(blob);
